CREATE TABLE integration_connectors(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,code VARCHAR(64) NOT NULL,provider VARCHAR(64) NOT NULL,version VARCHAR(32) NOT NULL,direction VARCHAR(32) NOT NULL,protocol VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,configuration JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_connector_tenant_code UNIQUE(tenant_id,code));
CREATE TABLE integration_jobs(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,connector_id UUID NOT NULL REFERENCES integration_connectors(id),execution_type VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ,correlation_id UUID NOT NULL,retry_count INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE integration_audit(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,connector_id UUID,integration_job_id UUID,action VARCHAR(64) NOT NULL,result VARCHAR(32) NOT NULL,message TEXT,correlation_id UUID,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE integration_retry_queue(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,job_id UUID NOT NULL,payload JSONB NOT NULL,error TEXT NOT NULL,available_at TIMESTAMPTZ NOT NULL,attempts INT NOT NULL DEFAULT 0,dead_letter BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_connectors_tenant_status ON integration_connectors(tenant_id,status);CREATE INDEX idx_jobs_tenant_status ON integration_jobs(tenant_id,status);CREATE INDEX idx_audit_tenant_time ON integration_audit(tenant_id,created_at);CREATE INDEX idx_retry_available ON integration_retry_queue(tenant_id,available_at,dead_letter);
